import { css } from 'ecij';

/*
 * The grid only has the class names generated by ecij: they are stable between builds,
 * as they are hashed from the file path, the declaration order and the variable name,
 * but they are not part of the API. Selectors interpolate the variables, like `.${cellClassname}`.
 *
 * Most of these rules have one class, so the later rule wins: keep the declarations in this order,
 * the variants after `cellClassname`, and `headerCellRangeSelectedClassname` after `rowHeaderCellClassname`.
 */

export const cellClassname = css`
  @layer rdg.Cell {
    /* max-content does not work with size containment
     * dynamically switching between different containment styles incurs a heavy relayout penalty
     * Chromium bug: at odd zoom levels or subpixel positioning,
     * layout/paint/style containment can make cell borders disappear
     *   https://issues.chromium.org/issues/40840864
     */
    position: relative; /* needed for absolute positioning to work */
    padding-block: 0;
    padding-inline: 12px;
    align-content: center;
    background-color: inherit;

    white-space: nowrap;
    overflow: clip;
    text-overflow: ellipsis;
    outline: none;

    /*
     * The active cell box is only drawn when the cell isn't in the cell selection, for example when the selection is cleared:
     * the selection draws the selected cells with its background and the border around each range.
     */
    &[aria-selected='true']::before {
      /* drawn on a pseudo element inside the cell, like the border around the selected ranges, so both line up */
      content: '';
      position: absolute;
      inset: 0;
      pointer-events: none;
      border: var(--rdg-selection-width) solid var(--rdg-selection-color);
    }

    /*
     * Header cells and row header cells are highlighted with their background when selected,
     * so the box is only drawn in the data area. It still shows when they are focused with the keyboard,
     * otherwise there would be no focus indicator.
     */
    &[role='columnheader'][aria-selected='true']:not(:focus-visible)::before {
      content: none;
    }
  }
`;

// every frozen cell is sticky, and has a line on its side facing the scrolling columns,
// so the frozen columns are separated from each other and from the scrolling columns
export const cellFrozenStartClassname = css`
  @layer rdg.Cell {
    position: sticky;
    /* Should have a higher value than 0 to show up above unfrozen cells */
    z-index: 1;
    border-inline-end: var(--rdg-border-width) solid var(--rdg-border-color);
  }
`;

export const cellFrozenEndClassname = css`
  @layer rdg.Cell {
    position: sticky;
    z-index: 1;
    border-inline-start: var(--rdg-border-width) solid var(--rdg-border-color);
  }
`;

export const cellRangeSelectedClassname = css`
  @layer rdg.Cell {
    background-color: var(--rdg-cell-selection-background-color);

    /* the selection draws the selected cells with its background and the border around each range */
    &[aria-selected='true']::before {
      content: none;
    }
  }
`;

// draws the border around each selected range, on the edges that the cell is on
export const cellRangeEdgeClassname = css`
  @layer rdg.Cell {
    &::after {
      content: '';
      position: absolute;
      inset: 0;
      pointer-events: none;
      border: 0 solid var(--rdg-cell-selection-border-color);
    }
  }
`;

// the edges are always set with `cellRangeEdgeClassname`, which they override
export const cellRangeEdgeTopClassname = css`
  @layer rdg.Cell {
    &.${cellRangeEdgeClassname}::after {
      border-block-start-width: var(--rdg-cell-selection-border-width);
    }
  }
`;

export const cellRangeEdgeBottomClassname = css`
  @layer rdg.Cell {
    &.${cellRangeEdgeClassname}::after {
      border-block-end-width: var(--rdg-cell-selection-border-width);
    }
  }
`;

export const cellRangeEdgeStartClassname = css`
  @layer rdg.Cell {
    &.${cellRangeEdgeClassname}::after {
      border-inline-start-width: var(--rdg-cell-selection-border-width);
    }
  }
`;

export const cellRangeEdgeEndClassname = css`
  @layer rdg.Cell {
    &.${cellRangeEdgeClassname}::after {
      border-inline-end-width: var(--rdg-cell-selection-border-width);
    }
  }
`;

export const rowHeaderCellClassname = css`
  @layer rdg.Cell {
    background-color: var(--rdg-header-background-color);
    color: var(--rdg-header-color);
    text-align: center;
    cursor: default;
    user-select: none;

    /* highlighted with its background when selected, the box only shows when it is focused with the keyboard */
    &[aria-selected='true']:not(:focus-visible)::before {
      content: none;
    }
  }
`;

// highlights the row header cells of the selected rows, and the header cells of the selected columns
export const headerCellRangeSelectedClassname = css`
  @layer rdg.HeaderCell {
    background-color: var(--rdg-header-selection-background-color);
    color: var(--rdg-header-selection-color);
  }
`;

export const cellResizableClassname = css`
  @layer rdg.HeaderCell {
    touch-action: none;
  }
`;

export const resizeHandleClassname = css`
  @layer rdg.HeaderCell {
    cursor: col-resize;
    position: absolute;
    inset-block-start: 0;
    inset-inline-end: 0;
    inset-block-end: 0;
    inline-size: 10px;
  }
`;

// prevents text selection while selecting cells with a pointer
export const cellSelectingClassname = css`
  @layer rdg.Root {
    user-select: none;
  }
`;
